function rememberDraft(value){try{if(value.text)localStorage.setItem(DRAFT_RECOVERY_KEY,JSON.stringify(value));else localStorage.removeItem(DRAFT_RECOVERY_KEY)}catch{}}
function Mark(){return <svg className="mark" viewBox="0 0 90 60" fill="none" aria-hidden="true"><path fill="currentColor" d="M3 46C19 40 30 29 44 35C36 39 40 44 50 46C62 50 72 43 87 45C62 48 60 58 38 51C24 46 19 43 3 46Z"/><path d="M43 39C58 29 53 9 62 5M48 43C59 36 64 31 69 22" stroke="currentColor" strokeWidth="1.5"/><ellipse cx="63" cy="5" rx="3" ry="5" transform="rotate(35 63 5)" fill="currentColor"/><ellipse cx="70" cy="21" rx="2.6" ry="4" transform="rotate(35 70 21)" fill="currentColor"/></svg>}
function SourceLinks({output,onOpen}){return <div className="native-sources">{output?.evidence?.map(e=><button key={e.revisionId} onClick={()=>onOpen(e.noteId)}><Link2Icon/><span>{e.text.slice(0,90)}{e.text.length>90?'…':''}</span><small>{e.valid?(sourceLabels[e.sourceKind]||'Note').toUpperCase():'OLDER VERSION'}</small></button>)}</div>}
function Rating({output,onRate}){
  const [reason,setReason]=useState(output?.rating?.reason||'');
  const [comment,setComment]=useState(output?.rating?.comment||'');
  useEffect(()=>{setReason(output?.rating?.reason||'');setComment(output?.rating?.comment||'')},[output?.id]);
  if(!output)return null;
  const sameBad=output.rating?.rating==='bad'&&output.rating.reason===reason&&(output.rating.comment||'')===comment;
  return <div className="native-rating"><span>Was this useful?</span><button className={output.rating?.rating==='good'?'on':''} aria-pressed={output.rating?.rating==='good'} onClick={()=>onRate(output,output.rating?.rating==='good'?'clear':'good','','')}>Good</button><button className={output.rating?.rating==='bad'?'on bad':''} aria-pressed={output.rating?.rating==='bad'} onClick={()=>onRate(output,sameBad?'clear':'bad',reason,comment)}>{output.rating?.rating==='bad'&&!sameBad?'Update Bad':'Bad'}</button><select value={reason} onChange={e=>setReason(e.target.value)} aria-label="Optional reason"><option value="">Reason (optional)</option><option value="incorrect">Fact is wrong</option><option value="not-my-taste">Not my taste</option><option value="not-now">Not now</option><option value="too-vague">Too vague</option><option value="repeated">Repeated idea</option></select>{reason==='incorrect'&&<input className="native-correction" value={comment} onChange={e=>setComment(e.target.value)} maxLength={500} placeholder="What was wrong? (optional)" aria-label="Correction (optional)"/>}</div>
}
