function Activity({label}){return <div className="ai-activity" role="status"><span className="ai-activity-mark" aria-hidden="true"><i/><i/><i/></span><span>{label}</span><span className="ai-activity-track" aria-hidden="true"/></div>}
function trapCaptureFocus(event){
  if(event.key!=='Tab')return;
  const items=[...event.currentTarget.querySelectorAll('button:not(:disabled),textarea:not(:disabled),input:not(:disabled):not([type="hidden"]),select:not(:disabled),a[href]')].filter(item=>item.getClientRects().length);
  if(!items.length)return;
  const first=items[0],last=items[items.length-1];
  if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}
  else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}
}
function SavedImage({attachment}){
  const [src,setSrc]=useState('');
  useEffect(()=>{let current=true;api.readAttachment(attachment.id).then(data=>{if(current)setSrc(`data:${data.mediaType};base64,${data.dataBase64}`)}).catch(()=>{});return()=>{current=false}},[attachment.id]);
  return src?<img src={src} alt={attachment.fileName||'Attached image'}/>:<span className="image-loading">Loading image…</span>;
}
function NoteCard({note,selected,saved,onSelect}){
  const hasImage=note.attachments?.length>0;
  const Icon=hasImage?ImageIcon:FileTextIcon;
  const kind=note.isDemo?'Demo note':note.originKind==='generated'?'Generated draft':sourceLabels[note.sourceKind]||'Note';
  return <button data-note-id={note.id} className={'note-row note-card'+(selected?' selected':'')+(saved?' just-saved':'')} onClick={()=>onSelect(note.id)} aria-pressed={selected}>
    <span className="note-card-head"><span className="note-card-kind"><Icon/>{kind}</span><time>{new Date(note.date).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}</time></span>
    <span className="note-card-body"><span className="note-card-thread" aria-hidden="true"/><span className="note-card-text">{note.text||'Image note'}</span>{hasImage&&<span className="note-card-thumbnail"><SavedImage attachment={note.attachments[0]}/></span>}</span>
    {note.articleStatus==='ready'&&note.articleTitle&&<span className="note-card-article"><span>ARTICLE / {note.articleSiteName||'SOURCE'}</span><strong>{note.articleTitle}</strong></span>}
    <span className="note-card-foot"><span>{note.aiExcluded?<><LockClosedIcon/>AI excluded</>:hasImage?`${note.attachments.length} image${note.attachments.length===1?'':'s'}`:'Open fragment'}</span><ArrowRightIcon/></span>
  </button>;
}
function ArticlePreview({note,onOpen,onRetry}){
  if(!note.sourceUrl)return null;
  const ready=note.articleStatus==='ready';
  return <section className="inspector-article" aria-label="Article preview">
    <span className="eyebrow">SAVED ARTICLE / EXTERNAL SOURCE</span>
    {ready?<><h3>{note.articleTitle||note.articleSiteName||'Article'}</h3>{note.articleDescription&&<p>{note.articleDescription}</p>}<small>{note.articleSiteName}</small></>:<p>{note.articleStatus==='failed'?'Could not load the article preview. Your link is saved.':note.articleStatus==='pending'||note.articleStatus==='running'?'Finding article details…':'Your link is saved.'}</p>}
    <div><button type="button" className="secondary" onClick={()=>onOpen(note.id)}><Link2Icon/>Open original</button>{note.articleStatus==='failed'&&<button type="button" className="text-button" onClick={()=>onRetry(note.id)}><ReloadIcon/>Try preview again</button>}</div>
  </section>;
}
function ManagedBackups({items,loading,error,onRefresh,onDelete}){
  return <section className="managed-backups"><div className="managed-backups-head"><div><h3>アプリ内バックアップ</h3><p>取り込みや復元の前にpureが作成したファイルです。手動で保存したバックアップは含まれません。</p></div><button className="text-button" onClick={onRefresh} disabled={loading}><ReloadIcon/>再確認</button></div>
    {loading?<p role="status">バックアップを確認中…</p>:error?<p role="alert">{error}</p>:items.length?<div className="managed-backup-list">{items.map(item=><div className="managed-backup-row" key={item.name}><div><strong>{item.name}</strong><small>{new Date(item.modifiedAt).toLocaleDateString('ja-JP',{year:'numeric',month:'long',day:'numeric'})} · {Math.ceil(item.size/1024)} KB</small><span className={item.status==='contains-deleted'?'managed-backup-warning':''}>{item.status==='contains-deleted'?`完全削除したメモが${item.deletedCount}件残っています`:item.status==='unreadable'?'ファイルを確認できませんでした':'このMacで完全削除したメモは見つかりませんでした'}</span></div><button className="text-button" onClick={()=>onDelete(item.name)}><TrashIcon/>ファイルを削除</button></div>)}</div>:<p>アプリ内バックアップはありません。</p>}
    <p>別の場所に保存・コピーしたバックアップはここから確認も削除もできません。不要な場合は保存先で削除してください。</p>
  </section>;
}
